package com.franco.desco.domain.delivery;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class DeliveryModels{private DeliveryModels(){}public record Summary(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoBrutoKg,BigDecimal taraKg,BigDecimal pesoRechazadoKg,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String estadoProceso,Long operativoVentaId,String operativo,Long socioId,String numeroDocumento,String socioNombre,BigDecimal valorizacion){}public record Header(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoBrutoKg,BigDecimal taraKg,BigDecimal pesoNetoKg,BigDecimal pesoRechazadoKg,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String ticketBalanza,String observacion,String estadoProceso,Long predioId,String predioCodigo,Long operativoVentaId,String operativo,String numeroDocumento,String socioNombre){}public record DetailLine(Long entregaDetalleId,Integer variedadPaltaId,String variedad,Long condicionComercialId,String condicion,Long precioComercialId,BigDecimal kilogramos,BigDecimal precioBase,BigDecimal precioAplicado,BigDecimal importe){}public record Incident(Long incidenciaId,String tipoIncidencia,String severidad,BigDecimal pesoAfectadoKg,String descripcion,String estadoIncidencia){}public record File(Long archivoId,String nombreOriginal,String mimeType,String secureUrl,String categoria,String descripcion,Instant fechaCarga){}public record Detail(Header entrega,List<DetailLine>detalles,List<Incident>incidencias,List<File>archivos){public Detail{detalles=detalles==null?List.of():List.copyOf(detalles);incidencias=incidencias==null?List.of():List.copyOf(incidencias);archivos=archivos==null?List.of():List.copyOf(archivos);}}}
